// Real per-locale strings extracted from jQuery UI 1.10.4's own
// `ui/i18n/jquery.ui.datepicker-*.js` files (upstream GitHub tag --
// npm's own published package drops these, matching the same gap
// `DatepickerView.php`'s own former `DATEPICKER_LOCALES` docblock
// already documented) and jquery-timepicker-addon's own vendored
// `src/i18n/jquery-ui-timepicker-*.js` files. Exactly the two
// authoritative locale lists those same classes' own
// `DATEPICKER_LOCALES`/`TIMEPICKER_LOCALES` constants named --
// every one of `Lang::langInfo()['jquery_code']`'s 67/39 real
// matchable values, not a hand-picked subset of this app's own
// currently-installed languages (a newly-installed language with a
// matching code should get real translations without this file
// needing a re-generation pass).

export interface DatepickerLocale {
  monthNames: string[];
  monthNamesShort: string[];
  dayNames: string[];
  dayNamesMin: string[];
  firstDay: number;
  isRTL: boolean;
  showMonthAfterYear: boolean;
  yearSuffix: string;
  prevText: string;
  nextText: string;
}

export interface TimepickerLocale {
  currentText: string;
  closeText: string;
  timeText: string;
  hourText: string;
  minuteText: string;
}

